fn solve(n: i8, m: i8, horizontal: Vec<char>, vertical: Vec<char>) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}

fn check_disconnected(n: i8, m: i8, horizontal: &Vec<char>, vertical: &Vec<char>) -> bool {
    // Convert to usize for indexing
    let n_usize = n as usize;
    let m_usize = m as usize;

    // Corner arrows
    let h_first = horizontal[0];
    let h_last = horizontal[n_usize - 1];
    let v_first = vertical[0];
    let v_last = vertical[m_usize - 1];

    // Check the four disconnect conditions
    (h_first == '>' && v_first == 'v') ||
    (h_first == '<' && v_last == 'v') ||
    (h_last  == '>' && v_first == '^') ||
    (h_last  == '<' && v_last == '^')
}

